solver = str(working_dir / "pymapdl_solve_bc.py")
PARN = 2   # LOW-only, TWO cases at a time, each @ nproc (user 2026-07-28)

# eligible = has mesh + low wall csv synced + not yet done
eligible = []
for ci in case_list:
    if not (mesh_dir / f"solid_{PLAQUE}_{ci}.msh").exists():
        no_msh.append(ci); continue
    if not (wall_dir / "low" / f"wall_low_case_{ci}.csv").exists():
        waiting_wall.append(ci); continue
    if (results_root / f"case_{ci}" / f"FC_case_{ci}_low.vtk").exists():
        continue
    eligible.append(ci)
print(f"[{PLAQUE}] LOW-only: {len(eligible)} eligible this pass, {PARN} at a time @ nproc {args.nproc} each")

def spawn_low(ci):
    case_dir = results_root / f"case_{ci}"; case_dir.mkdir(parents=True, exist_ok=True)
    low_dir = case_dir / "low"; low_dir.mkdir(exist_ok=True)
    low_vtk = case_dir / f"FC_case_{ci}_low.vtk"
    _, low_port = _ports(ci)   # each concurrent case gets its own rotating port
    # solve_bc builds its own cdb in low_dir (meshprep + write), then solves low.
    p = subprocess.Popen(["python", solver, str(ci), "low",
                          str(args.nproc), str(low_dir), str(low_port), str(low_vtk), PLAQUE])
    return {"ci": ci, "p": p, "low_dir": low_dir, "low_vtk": low_vtk}

# process eligible cases PARN at a time
for i in range(0, len(eligible), PARN):
    group = eligible[i:i+PARN]
    print(f"\n\n******** LOW group {group} @ nproc {args.nproc} each ********\n")
    try:
        running = [spawn_low(ci) for ci in group]
        for r in running:
            r["rc"] = r["p"].wait()
        for r in running:
            if r["low_vtk"].exists():
                shutil.rmtree(r["low_dir"], ignore_errors=True)
                print(f"************ Finished case {r['ci']} (LOW only) ************")
            else:
                print(f"case {r['ci']}: INCOMPLETE (low missing, rc={r.get('rc')}) - retry next pass")
    except Exception as e:
        print(f"Error group {group}: {e}")
    # clean any leftover live ANSYS before the next group (exit can segfault)
    os.system("pkill -9 -f '[a]nsys251' 2>/dev/null; pkill -9 -f '[a]nsys.e' 2>/dev/null; true")

