import time as _time, signal
case_list = list(range(args.start, args.end))
solver = str(working_dir / "pymapdl_solve_bc.py")
PARN = 3            # worker-pool size: keep this many low solves running at once
TIMEOUT = 9000      # per-case hard cap (s); kills pathological out-of-core grinders + frees their disk
MIN_FREE_GB = 450   # don't START a new case if free disk below this (out-of-core scratch can be ~350GB/case)

# eligible = has mesh + low wall csv synced + not yet done
eligible = []
for ci in case_list:
    if not (mesh_dir / f"solid_{PLAQUE}_{ci}.msh").exists():
        no_msh.append(ci); continue
    if not (wall_dir / "low" / f"wall_low_case_{ci}.csv").exists():
        waiting_wall.append(ci); continue
    if (results_root / f"case_{ci}" / f"FC_case_{ci}_low.vtk").exists():
        continue
    eligible.append(ci)
print(f"[{PLAQUE}] LOW-only: {len(eligible)} eligible this pass, POOL of {PARN} @ nproc {args.nproc}", flush=True)

def free_gb():
    st = os.statvfs(str(results_root)); return st.f_bavail * st.f_frsize / 1e9

def spawn_low(ci):
    case_dir = results_root / f"case_{ci}"; case_dir.mkdir(parents=True, exist_ok=True)
    low_dir = case_dir / "low"; low_dir.mkdir(exist_ok=True)
    low_vtk = case_dir / f"FC_case_{ci}_low.vtk"
    _, low_port = _ports(ci)   # each concurrent case gets its own rotating port
    # start_new_session -> solve_bc is its own process-group leader, so on TIMEOUT we
    # can kill the whole group (python + its MAPDL child) with one killpg.
    p = subprocess.Popen(["python", solver, str(ci), "low",
                          str(args.nproc), str(low_dir), str(low_port), str(low_vtk), PLAQUE],
                         start_new_session=True)
    return {"ci": ci, "p": p, "low_dir": low_dir, "low_vtk": low_vtk, "start": _time.time()}

def finalize(r, reason):
    ci = r["ci"]
    if r["low_vtk"].exists():
        print(f"************ Finished case {ci} (LOW only) ************", flush=True)
    else:
        print(f"case {ci}: INCOMPLETE ({reason}) - retry next pass", flush=True)
    # always drop scratch (cdb/rst/db) whether ok or failed; final vtk is in parent case dir
    shutil.rmtree(r["low_dir"], ignore_errors=True)
    try:
        (results_root / f"case_{ci}" / "total_solid1.cdb").unlink()
    except FileNotFoundError:
        pass

# WORKER POOL: keep up to PARN low solves running; refill as each finishes, so one
# slow (out-of-core) case only occupies ONE slot instead of blocking a whole group.
running = {}
ei = 0
while ei < len(eligible) or running:
    while len(running) < PARN and ei < len(eligible):
        if running and free_gb() < MIN_FREE_GB:
            print(f"[disk] free {free_gb():.0f}GB < {MIN_FREE_GB}GB -> holding new spawns ({len(running)} running)", flush=True)
            break
        ci = eligible[ei]; ei += 1
        running[ci] = spawn_low(ci)
        print(f"[pool] started case {ci} ({len(running)}/{PARN} running, {free_gb():.0f}GB free)", flush=True)
    _time.sleep(5)
    for ci in list(running):
        r = running[ci]; rc = r["p"].poll()
        if rc is None and (_time.time() - r["start"]) > TIMEOUT:
            print(f"case {ci}: TIMEOUT >{TIMEOUT}s - killing process group", flush=True)
            try:
                os.killpg(os.getpgid(r["p"].pid), signal.SIGKILL)
            except Exception:
                pass
            r["p"].wait(); rc = -9
        if rc is not None:
            finalize(r, f"rc={rc}")
            del running[ci]

