peakvtu=\$(ls solid_data/case_*/ansys_results_type1_expB_new/FC_case_*_peak.vtu 2>/dev/null|wc -l);
run=\$(pgrep -af '[p]ymapdl_solve_peak.py'|grep -oE 'solve_peak.py [0-9]+'|grep -oE '[0-9]+'|tr '\n' ' ');
nrun=\$(pgrep -af '[p]ymapdl_solve_peak.py'|grep -oE 'solve_peak.py [0-9]+'|wc -l);
faillist=\$(grep 'INCOMPLETE' PEAK_batch.log|grep -oE 'case [0-9]+'|sort -u|grep -oE '[0-9]+'|while read c; do [ -f solid_data/case_\$c/ansys_results_type1_expB_new/FC_case_\${c}_peak.vtu ]||echo -n \"\$c \"; done);
pass=\$(grep -c 'PEAK PASS END' PEAK_batch.log);
echo \"성공=\$((peakvtu-403)) 총\$peakvtu/1000 실행중=\$nrun(\$run) 남은=\$((162-(peakvtu-403)-nrun)) passEND=\$pass\";
echo \"failcases: \$faillist\";
echo wrap=\$(pgrep -cf '[r]un_peak_batch.sh') orch=\$(pgrep -cf '[p]ymapdl_peak_pool.py') disk_avail=\$(df -h /home|tail -1|awk '{print \$4}') disk_pct=\$(df -h /home|tail -1|awk '{print \$5}');
du -sh solid_data/case_*/ansys_results_type1_expB_new/peaktmp 2>/dev/null|sort -rh|head -4"

ssh ws2 "cd /home/jeff/project/54_analysis;
echo '=== 304 / 313 최근 실패 사유 ===';
grep -nE 'case 304|case 313' PEAK_batch.log|tail -8;
echo '--- 304/313 관련 에러 유형 ---';
awk '/\[pool\] started PEAK case 304/{f=1} f&&/case 304: (INCOMPLETE|TIMEOUT)/{print \"304: \"\$0; f=0}' PEAK_batch.log|tail -2;
awk '/\[pool\] started PEAK case 313/{f=1} f&&/case 313: (INCOMPLETE|TIMEOUT)/{print \"313: \"\$0; f=0}' PEAK_batch.log|tail -2;
echo '--- 메쉬 크기 ---';
for c in 304 313 653; do [ -f LAP_mesh/solid_LAP_\$c.msh ]&&echo \"case \$c: \$(du -h LAP_mesh/solid_LAP_\$c.msh|cut -f1)\"||echo \"case \$c: 메쉬없음\"; done"

ssh ws2 "cd /home/jeff/project/54_analysis;
echo '=== 304 마지막 시도 에러 (line ~36396 앞) ===';
sed -n '36340,36396p' PEAK_batch.log 2>/dev/null|grep -iE 'error|fail|traceback|exceed|memory|negative|converg|pivot|singular|gRPC|not enough|reshape|Insufficient|out of' |tail -15"

ssh ws2 "cd /home/jeff/project/54_analysis;
echo '=== 304/313 실행중 아닌지 확인 ===';
pgrep -af '[p]ymapdl_solve_peak.py'|grep -oE 'solve_peak.py [0-9]+'|grep -E ' (304|313)\$' && echo 'WARNING 실행중' || echo 'OK 실행안함';
echo '=== 메쉬 옆으로 치움 (.NEGJAC) ===';
for c in 304 313; do
  if [ -f LAP_mesh/solid_LAP_\$c.msh ]; then mv LAP_mesh/solid_LAP_\$c.msh LAP_mesh/solid_LAP_\$c.msh.NEGJAC; echo \"case \$c: moved -> .NEGJAC\"; else echo \"case \$c: 이미 없음\"; fi;
done;
echo '=== 잔여 스크래치 정리 ===';
for c in 304 313; do rm -rf solid_data/case_\$c/ansys_results_type1_expB_new/peaktmp; done;
echo '=== 확인 ===';
for c in 304 313; do [ -f LAP_mesh/solid_LAP_\$c.msh ]&&echo \"\$c STILL\"||echo -n \"\$c \"; done; echo 'moved. disk:'; df -h /home|tail -1|awk '{print \$4\" free\"}'"

